// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonAdmin = address(0x123);
        address initialOwner = c.owner();
        vm.prank(nonAdmin);
        c.setOwner(address(0x456));
        assertTrue(c.owner() == initialOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner1 = address(0x123);
        address newOwner2 = address(0x456);
        address admin = address(this);
        vm.prank(admin);
        c.setOwner(newOwner1);
        vm.prank(admin);
        bool ok;
        try c.setOwner(newOwner2) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The admin is the address that deployed C (this contract in Foundry)
        address newOwner = address(0x1);
        bool result;
        (result, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        assertTrue(result);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        bool success;
        vm.prank(address(this));
        try c.setOwner(address(1)) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success == true);
    }
}
